  it("extracts a single-quoted caption", () => {
    expect(extractDescribeCaption("describe('Other');")).toBe("Other");
  });

  it("returns null when there is no describe call", () => {
    expect(extractDescribeCaption("no describe here")).toBeNull();
  });
});

