import type { Course } from "../data/types";

describe("courseLoader", () => {
  let courses: Course[];

  beforeAll(async () => {
    courses = await loadAllCourses();
  });

  it("loads every expected module", () => {
    const slugs = courses.map((c) => c.slug);
    for (const expected of [
      "shapes",
      "color",
      "transform",
      "custom-shapes",
      "curves",
      "typography",
      "image",
      "math",
      "vectors",
      "random-noise",
      "dom",
      "events",
