import { describe, it, expect, jest, beforeEach } from "@jest/globals";
import { render, fireEvent } from "@testing-library/react-native";
import Button from "./Button";
import { renderWithProviders } from "../test/renderWithProviders";

describe("Button", () => {
  const onPress = jest.fn();

  beforeEach(() => {
    onPress.mockClear();
  });

  it("renders the title and fires onPress when pressed", () => {
    const { getByText } = renderWithProviders(
      <Button title="Go" onPress={onPress} />
    );
    fireEvent.press(getByText("Go"));
    expect(onPress).toHaveBeenCalledTimes(1);
  });

  it("uses the title as the default accessibility label", () => {
    const { getByLabelText } = renderWithProviders(
      <Button title="Start" onPress={onPress} />
    );
    expect(getByLabelText("Start")).toBeTruthy();
  });

  it("honors an explicit accessibilityLabel", () => {
    const { getByLabelText } = renderWithProviders(
      <Button title="Start" onPress={onPress} accessibilityLabel="Launch" />
    );
    expect(getByLabelText("Launch")).toBeTruthy();
  });

  it("does not fire when disabled", () => {
    const { getByLabelText } = renderWithProviders(
      <Button title="Start" onPress={onPress} disabled />
    );
    fireEvent.press(getByLabelText("Start"));
    expect(onPress).not.toHaveBeenCalled();
  });

  it("renders both variants without throwing", () => {
    renderWithProviders(<Button title="Primary" onPress={onPress} variant="primary" />);
    renderWithProviders(<Button title="Outline" onPress={onPress} variant="outline" />);
  });
});

import { describe, it, expect, jest, beforeEach } from "@jest/globals";
import { render, fireEvent } from "@testing-library/react-native";
import Breadcrumbs from "./Breadcrumbs";
import { renderWithProviders } from "../test/renderWithProviders";
import { mockRouterModule, mockRouter } from "../test/expoRouterMock";

jest.mock("expo-router", () => mockRouterModule);

describe("Breadcrumbs", () => {
  beforeEach(() => {
    mockRouter.push.mockClear();
  });

  it("renders every segment label", () => {
    const { getByText } = renderWithProviders(
      <Breadcrumbs
        segments={[
          { label: "Courses", href: "/" },
          { label: "Shapes", href: "/courses/shapes" },
          { label: "Circles" },
        ]}
      />
    );
    expect(getByText("Courses")).toBeTruthy();
    expect(getByText("Shapes")).toBeTruthy();
    expect(getByText("Circles")).toBeTruthy();
  });

  it("navigates to a href when a non-last segment is pressed", () => {
    const { getByLabelText } = renderWithProviders(
      <Breadcrumbs
        segments={[
          { label: "Courses", href: "/" },
          { label: "Shapes" },
        ]}
      />
    );
    fireEvent.press(getByLabelText("Go to Courses"));
    expect(mockRouter.push).toHaveBeenCalledWith("/");
  });

  it("does not make the last segment clickable", () => {
    const { queryByLabelText } = renderWithProviders(
      <Breadcrumbs
        segments={[
          { label: "Courses", href: "/" },
          { label: "Shapes", href: "/courses/shapes" },
        ]}
      />
    );
    expect(queryByLabelText("Go to Shapes")).toBeNull();
  });
});

import { describe, it, expect } from "@jest/globals";
import { screen, render } from "@testing-library/react-native";
import { MaterialCommunityIcons } from "@expo/vector-icons";
import ModuleCover from "./ModuleCover";
import { renderWithProviders } from "../test/renderWithProviders";

describe("ModuleCover", () => {
  it("renders a lock icon when locked", () => {
    renderWithProviders(<ModuleCover slug="shapes" color="#ED225D" locked />);
    expect(screen.UNSAFE_queryAllByType(MaterialCommunityIcons).length).toBe(1);
  });

  it("renders a check icon when completed", () => {
    renderWithProviders(<ModuleCover slug="shapes" color="#ED225D" completed />);
    expect(screen.UNSAFE_queryAllByType(MaterialCommunityIcons).length).toBe(1);
  });

  it("renders the animated variant for unlocked covers (no icon)", () => {
    renderWithProviders(<ModuleCover slug="shapes" color="#ED225D" />);
    expect(screen.UNSAFE_queryAllByType(MaterialCommunityIcons).length).toBe(0);
  });

  it("falls back to the default variant for unknown slugs", () => {
    expect(() =>
      renderWithProviders(<ModuleCover slug="unknown-slug" color="#ED225D" />)
    ).not.toThrow();
  });

  it("renders without a provider tree when passed minimal props", () => {
    expect(() =>
      render(<ModuleCover slug="math" color="#000000" />)
    ).not.toThrow();
  });
});

import { describe, it, expect, jest, beforeEach } from "@jest/globals";
import { render, fireEvent } from "@testing-library/react-native";
import ExerciseCard from "./ExerciseCard";
import { renderWithProviders } from "../test/renderWithProviders";

describe("ExerciseCard", () => {
  const onContinue = jest.fn();

  beforeEach(() => {
    onContinue.mockClear();
  });

  it("renders title, module name and description", () => {
    const { getByText } = renderWithProviders(
      <ExerciseCard
        title="Circles"
        moduleName="Shapes"
        description="Draw a circle."
      />
    );
    expect(getByText("Circles")).toBeTruthy();
    expect(getByText("Shapes")).toBeTruthy();
    expect(getByText("Draw a circle.")).toBeTruthy();
  });

  it("fires onContinue when the unlocked card is pressed", () => {
    const { getByText } = renderWithProviders(
      <ExerciseCard
        title="Circles"
        moduleName="Shapes"
        description="Draw a circle."
        onContinue={onContinue}
      />
    );
    fireEvent.press(getByText("Circles"));
    expect(onContinue).toHaveBeenCalledTimes(1);
  });

  it("shows the Continue button only for the current unlocked exercise", () => {
    const { getByText, rerender } = renderWithProviders(
      <ExerciseCard
        title="Circles"
        moduleName="Shapes"
        description="Draw a circle."
        isCurrent
        onContinue={onContinue}
      />
    );
    expect(getByText("Continue")).toBeTruthy();

    rerender(
      <ExerciseCard
        title="Circles"
        moduleName="Shapes"
        description="Draw a circle."
        onContinue={onContinue}
      />
    );
    expect(() => getByText("Continue")).toThrow();
  });

  it("marks the card as locked and refuses presses", () => {
    const { getByLabelText, getByText } = renderWithProviders(
      <ExerciseCard
        title="Circles"
        moduleName="Shapes"
        description="Draw a circle."
        locked
        lockHint="Ellipses"
        onContinue={onContinue}
      />
    );
    expect(getByLabelText(/Circles \(locked/)).toBeTruthy();
    expect(getByText('Complete "Ellipses" to unlock this one.')).toBeTruthy();
    fireEvent.press(getByLabelText(/Circles \(locked/));
    expect(onContinue).not.toHaveBeenCalled();
  });

  it("shows the generic lock message when no lock hint is given", () => {
    const { getByText } = renderWithProviders(
      <ExerciseCard
        title="Circles"
        moduleName="Shapes"
        description="Draw a circle."
        locked
      />
    );
    expect(getByText("Complete the current module to unlock this one.")).toBeTruthy();
  });
});

import { describe, it, expect, jest, beforeEach } from "@jest/globals";
import { render, fireEvent } from "@testing-library/react-native";
import { Text } from "react-native";
import Header from "./Header";
import { useDrawerContext } from "../contexts/DrawerContext";
import { renderWithProviders } from "../test/renderWithProviders";
import { mockRouterModule, mockRouter } from "../test/expoRouterMock";

jest.mock("expo-router", () => mockRouterModule);

function DrawerProbe() {
  const { isOpen } = useDrawerContext();
  return <Text testID="drawer-state">{isOpen ? "open" : "closed"}</Text>;
}

describe("Header", () => {
  beforeEach(() => {
    mockRouter.back.mockClear();
  });

  it("renders title and subtitle", () => {
    const { getByText } = renderWithProviders(
      <Header title="Shapes" subtitle="Module 1" />
    );
    expect(getByText("Shapes")).toBeTruthy();
    expect(getByText("Module 1")).toBeTruthy();
  });

  it("goes back via the router by default", () => {
    const { getByLabelText } = renderWithProviders(<Header title="Shapes" />);
    fireEvent.press(getByLabelText("Go back"));
    expect(mockRouter.back).toHaveBeenCalledTimes(1);
  });

  it("uses the provided onBack instead of the router", () => {
    const onBack = jest.fn();
    const { getByLabelText } = renderWithProviders(
      <Header title="Shapes" onBack={onBack} />
    );
    fireEvent.press(getByLabelText("Go back"));
    expect(onBack).toHaveBeenCalledTimes(1);
    expect(mockRouter.back).not.toHaveBeenCalled();
  });

  it("renders the hamburger and opens the drawer when showBack is false", () => {
    const { getByLabelText, getByTestId } = renderWithProviders(
      <>
        <Header title="Home" showBack={false} />
        <DrawerProbe />
      </>,
      { withDrawer: true }
    );
    fireEvent.press(getByLabelText("Open navigation drawer"));
    expect(getByTestId("drawer-state").props.children).toBe("open");
  });

  it("renders the right slot", () => {
    const { getByTestId } = renderWithProviders(
      <Header title="Shapes" right={<Text testID="right-slot">extra</Text>} />
    );
    expect(getByTestId("right-slot")).toBeTruthy();
  });
});

import { describe, it, expect } from "@jest/globals";
import { render, fireEvent } from "@testing-library/react-native";
import { Pressable, Text } from "react-native";
import DrawerProvider, { useDrawerContext } from "./DrawerContext";

function Probe() {
  const { isOpen, openDrawer, closeDrawer, toggleDrawer } = useDrawerContext();
  return (
    <>
      <Text testID="state">{isOpen ? "open" : "closed"}</Text>
      <Pressable testID="open" onPress={openDrawer} />
      <Pressable testID="close" onPress={closeDrawer} />
      <Pressable testID="toggle" onPress={toggleDrawer} />
    </>
  );
}

function renderProbe() {
  return render(
    <DrawerProvider>
      <Probe />
    </DrawerProvider>
  );
}

describe("DrawerProvider", () => {
  it("starts closed", () => {
    const { getByTestId } = renderProbe();
    expect(getByTestId("state").props.children).toBe("closed");
  });

  it("openDrawer and closeDrawer update the state", () => {
    const { getByTestId } = renderProbe();
    fireEvent.press(getByTestId("open"));
    expect(getByTestId("state").props.children).toBe("open");
    fireEvent.press(getByTestId("close"));
    expect(getByTestId("state").props.children).toBe("closed");
  });

  it("toggleDrawer flips the state", () => {
    const { getByTestId } = renderProbe();
    fireEvent.press(getByTestId("toggle"));
    expect(getByTestId("state").props.children).toBe("open");
    fireEvent.press(getByTestId("toggle"));
    expect(getByTestId("state").props.children).toBe("closed");
  });
});

import { describe, it, expect, jest, afterEach } from "@jest/globals";
import { render, fireEvent, waitFor } from "@testing-library/react-native";
import { Pressable, Text } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import ThemeProvider, { useThemeContext } from "./ThemeProvider";
import { DEFAULTS } from "../constants/Defaults";

function Probe() {
  const { colorScheme, ctaColor, derivedColors, toggleTheme, setCtaColor } =
    useThemeContext();
  return (
    <>
      <Text testID="scheme">{colorScheme}</Text>
      <Text testID="cta">{ctaColor}</Text>
      <Text testID="primary">{derivedColors.primary}</Text>
      <Pressable testID="toggle" onPress={toggleTheme} />
      <Pressable testID="setcolor" onPress={() => setCtaColor("#123456")} />
    </>
  );
}

function renderProbe() {
  return render(
    <ThemeProvider>
      <Probe />
    </ThemeProvider>
  );
}

afterEach(async () => {
  jest.restoreAllMocks();
  await AsyncStorage.clear();
});

describe("ThemeProvider", () => {
  it("provides light scheme with the default accent by default", () => {
    const { getByTestId } = renderProbe();
    expect(getByTestId("scheme").props.children).toBe("light");
    expect(getByTestId("cta").props.children).toBe(DEFAULTS.ctaColor);
    expect(getByTestId("primary").props.children).toBe(DEFAULTS.ctaColor);
  });

  it("toggles the color scheme", () => {
    const { getByTestId } = renderProbe();
    fireEvent.press(getByTestId("toggle"));
    expect(getByTestId("scheme").props.children).toBe("dark");
    fireEvent.press(getByTestId("toggle"));
    expect(getByTestId("scheme").props.children).toBe("light");
  });

  it("persists the accent color to AsyncStorage", async () => {
    const { getByTestId } = renderProbe();
    fireEvent.press(getByTestId("setcolor"));
    expect(getByTestId("cta").props.children).toBe("#123456");
    await waitFor(() =>
      expect(AsyncStorage.getItem("setting_ctaColor")).resolves.toBe("#123456")
    );
  });

  it("restores a persisted color scheme", async () => {
    await AsyncStorage.setItem("userColorScheme", "dark");
    const { getByTestId } = renderProbe();
    await waitFor(() =>
      expect(getByTestId("scheme").props.children).toBe("dark")
    );
  });

  it("restores a persisted accent color", async () => {
    await AsyncStorage.setItem("setting_ctaColor", "#ABCDEF");
    const { getByTestId } = renderProbe();
    await waitFor(() =>
      expect(getByTestId("cta").props.children).toBe("#ABCDEF")
    );
  });
});

import { describe, it, expect, jest, afterEach } from "@jest/globals";
import { render, waitFor } from "@testing-library/react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import StatusBarAccent from "./StatusBarAccent";
import { renderWithProviders } from "../test/renderWithProviders";

const mockStatusBar = jest.fn().mockImplementation(() => null);

jest.mock("expo-status-bar", () => ({
  StatusBar: mockStatusBar,
}));

function lastStatusBarProps() {
  const calls = mockStatusBar.mock.calls;
  return calls[calls.length - 1][0];
}

afterEach(async () => {
  jest.restoreAllMocks();
  mockStatusBar.mockClear();
  await AsyncStorage.clear();
});

describe("StatusBarAccent", () => {
  it("renders a visible status bar by default with a light-style accent", () => {
    renderWithProviders(<StatusBarAccent />);
    expect(mockStatusBar).toHaveBeenCalledTimes(1);
    expect(lastStatusBarProps()).toMatchObject({
      hidden: false,
      style: "dark",
      backgroundColor: "#FF69B4",
    });
  });

  it("hides the status bar when the user setting is 'false'", async () => {
    await AsyncStorage.setItem("setting_showStatusBar", "false");
    renderWithProviders(<StatusBarAccent />);
    await waitFor(() => expect(mockStatusBar).toHaveBeenCalled());
    expect(lastStatusBarProps().hidden).toBe(true);
  });

  it("renders in the dark scheme with the surface background", async () => {
    await AsyncStorage.setItem("userColorScheme", "dark");
    renderWithProviders(<StatusBarAccent />);
    await waitFor(() => expect(mockStatusBar).toHaveBeenCalled());
    expect(lastStatusBarProps().backgroundColor).toBe("#121317");
  });
});

