  count: number;
  longest: number;
  isNewDay: boolean;
  currentTier: number;
  nextTier: number;
  tierProgress: number;
}

function getDateString(date: Date): string {
  return date.toISOString().split("T")[0];
}

function getCurrentTierIndex(days: number): number {
  for (let i = STREAK_TIERS.length - 1; i >= 0; i--) {
    if (days >= STREAK_TIERS[i]) return i;
  }
  return -1;
}

