  new Function("module", "exports", "globalThis", `${code}\n;module.exports = exports;`)(m, m.exports, {});
  return m.exports;
}
const bundleExports = (() => {
  const sandbox = {};
  new Function("globalThis", bundleJs)(sandbox);
  return sandbox.__VAL_CORE;
