  "let t = 0; for (let i = 0; i < 10; i++) t += i;",
  "const obj = { render() {} };",
  "new p5.Vector(1, 2);",
  "vec.add(1, 2);",
  "fill(random(255), 0, 0);",
  "background(0);",
  "createCanvas(width, height);",
  "",
];
const ruleSets = [
  [],
  [{ type: "functionCall", name: "circle" }],
  [{ type: "functionCall", name: "translate", exactArgs: 2 }],
  [{ type: "functionCall", name: "line", minArgs: 4 }],
  [{ type: "functionExists", name: "draw" }],
  [{ type: "canvasSize", width: 400, height: 400 }],
  [{ type: "functionCall", name: "circle" }, { type: "functionExists", name: "draw" }, { type: "canvasSize", width: 200, height: 200 }],
];
let failures = 0;
function check(name, a, b) {
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    failures++;
    console.log("MISMATCH:", name, "\n  src:", JSON.stringify(a), "\n  bundle:", JSON.stringify(b));
  }
}
const { parse } = await import("@lezer/javascript");
for (const code of samples) {
  const tree = parse(code);
  const adapter = { cursor: () => tree.cursor(), slice: (f, t) => code.slice(f, t) };
  const a = srcExports.analyze(adapter);
  const b = bundleExports.analyze(adapter);
  check(`analyze(${JSON.stringify(code)})`, { ...a, functionDefs: [...a.functionDefs].sort() }, { ...b, functionDefs: [...b.functionDefs].sort() });
  for (const rules of ruleSets) {
    check(`evaluateRules(${JSON.stringify(code)}, ${JSON.stringify(rules)})`, srcExports.evaluateRules(a, rules), bundleExports.evaluateRules(a, rules));
  }
}
const invalid = [
  [{ type: "bogus" }],
  [{ type: "canvasSize", width: 400 }],
  [{ type: "functionCall", name: 123 }],
  [{ type: "pixelMatch", x: 0, y: 0, expected: [255, 0] }],
  [{ type: "expectedPixels", points: [] }],
  [{ name: "x" }],
];
for (const rules of invalid) check(`schemaErrors(${JSON.stringify(rules)})`, srcExports.schemaErrors(rules), bundleExports.schemaErrors(rules));

check("RULE_SCHEMAS keys", Object.keys(srcExports.RULE_SCHEMAS).sort(), Object.keys(bundleExports.RULE_SCHEMAS).sort());
check("RULE_TYPES", [...srcExports.RULE_TYPES].sort(), [...bundleExports.RULE_TYPES].sort());
check("PIXEL_DEFAULT_TOLERANCE", srcExports.PIXEL_DEFAULT_TOLERANCE, bundleExports.PIXEL_DEFAULT_TOLERANCE);
check("PIXEL_DEFAULT_MIN_PASS_FRACTION", srcExports.PIXEL_DEFAULT_MIN_PASS_FRACTION, bundleExports.PIXEL_DEFAULT_MIN_PASS_FRACTION);

console.log(failures === 0 ? "PARITY OK: source and bundle agree on all samples." : `PARITY FAILED with ${failures} mismatches.`);
EOF
